('index', 'idx_users_phone', 'CREATE UNIQUE INDEX idx_users_phone ON users(phone) WHERE phone IS NOT NULL')
('index', 'ix_ai_usage_created', 'CREATE INDEX ix_ai_usage_created ON ai_usage(created_at)')
('index', 'ix_assets_category', 'CREATE INDEX ix_assets_category ON assets(category)')
('index', 'ux_ai', 'CREATE UNIQUE INDEX ux_ai ON ai_index(source_type, source_id, chunk_kind)')
('table', 'ai_index', "CREATE TABLE ai_index (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  source_type TEXT NOT NULL,\n  source_id TEXT NOT NULL,\n  chunk_kind TEXT NOT NULL,\n  content TEXT NOT NULL,\n  embedding TEXT NOT NULL,\n  model TEXT NOT NULL,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n)")
('table', 'ai_usage', "CREATE TABLE ai_usage (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  uid TEXT,\n  kind TEXT NOT NULL,\n  prompt_tokens INTEGER NOT NULL DEFAULT 0,\n  completion_tokens INTEGER NOT NULL DEFAULT 0,\n  duration_ms INTEGER NOT NULL DEFAULT 0,\n  ok INTEGER NOT NULL DEFAULT 1,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n)")
('table', 'articles', "CREATE TABLE articles (\n  id TEXT PRIMARY KEY,\n  source_type TEXT NOT NULL,\n  source_id TEXT NOT NULL,\n  title TEXT NOT NULL,\n  layer TEXT NOT NULL,\n  domain TEXT NOT NULL,\n  steps TEXT NOT NULL,\n  lessons TEXT NOT NULL DEFAULT '[]',\n  author TEXT NOT NULL,\n  published_at TEXT NOT NULL DEFAULT (datetime('now'))\n)")
('table', 'assets', "CREATE TABLE assets (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  object_key TEXT NOT NULL UNIQUE,\n  filename TEXT NOT NULL,\n  category TEXT NOT NULL DEFAULT 'misc',\n  content_type TEXT NOT NULL DEFAULT '',\n  size_bytes INTEGER NOT NULL DEFAULT 0,\n  sha256 TEXT NOT NULL DEFAULT '',\n  note TEXT NOT NULL DEFAULT '',\n  uploaded_by TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n)")
('table', 'cases', "CREATE TABLE cases (\n  id TEXT PRIMARY KEY,\n  submission_id TEXT,\n  author_id TEXT,\n  title TEXT NOT NULL,\n  domain TEXT NOT NULL,\n  layer TEXT NOT NULL,\n  difficulty INTEGER NOT NULL,\n  version INTEGER NOT NULL,\n  status TEXT NOT NULL DEFAULT 'published',\n  payload TEXT NOT NULL,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  published_at TEXT\n)")
('table', 'meta', 'CREATE TABLE meta (\n  meta_key TEXT PRIMARY KEY,\n  value TEXT NOT NULL\n)')
('table', 'ops_snapshots', "CREATE TABLE ops_snapshots (\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\n  ts TEXT NOT NULL DEFAULT (datetime('now')),\n  requests INTEGER NOT NULL DEFAULT 0,\n  errors INTEGER NOT NULL DEFAULT 0,\n  avg_ms INTEGER NOT NULL DEFAULT 0,\n  rss_mb REAL NOT NULL DEFAULT 0,\n  disk_free_mb REAL NOT NULL DEFAULT 0\n)")
('table', 'progress', "CREATE TABLE progress (\n  user_id TEXT PRIMARY KEY,\n  payload TEXT NOT NULL,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now'))\n)")
('table', 'resource_slots', "CREATE TABLE resource_slots (\n  slot TEXT PRIMARY KEY,\n  asset_id INTEGER NOT NULL,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_by TEXT\n)")
('table', 'settings', "CREATE TABLE settings (\n  setting_key TEXT PRIMARY KEY,\n  value TEXT NOT NULL,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  updated_by TEXT\n)")
('table', 'sms_codes', "CREATE TABLE sms_codes (\n  phone TEXT PRIMARY KEY,\n  code TEXT NOT NULL,\n  expires_at INTEGER NOT NULL,\n  used INTEGER NOT NULL DEFAULT 0,\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n)")
('table', 'sqlite_sequence', 'CREATE TABLE sqlite_sequence(name,seq)')
('table', 'submissions', "CREATE TABLE submissions (\n  id TEXT PRIMARY KEY,\n  user_id TEXT NOT NULL,\n  title TEXT NOT NULL,\n  symptom TEXT NOT NULL,\n  resolution TEXT NOT NULL,\n  key_error TEXT,\n  timeline TEXT,\n  lessons TEXT NOT NULL DEFAULT '[]',\n  stack_tags TEXT NOT NULL DEFAULT '[]',\n  domain_hint TEXT,\n  status TEXT NOT NULL DEFAULT 'pending',\n  review_note TEXT,\n  created_at TEXT NOT NULL DEFAULT (datetime('now')),\n  reviewed_at TEXT\n)")
('table', 'user_activity', "CREATE TABLE user_activity (\n  user_id TEXT NOT NULL,\n  day TEXT NOT NULL,\n  hits INTEGER NOT NULL DEFAULT 1,\n  updated_at TEXT NOT NULL DEFAULT (datetime('now')),\n  PRIMARY KEY (user_id, day)\n)")
('table', 'users', "CREATE TABLE users (\n  id TEXT PRIMARY KEY,\n  login TEXT UNIQUE NOT NULL,\n  name TEXT,\n  avatar TEXT,\n  role TEXT NOT NULL DEFAULT 'user',\n  status TEXT NOT NULL DEFAULT 'active',\n  created_at TEXT NOT NULL DEFAULT (datetime('now'))\n, password_hash TEXT, phone TEXT)")
